CREATE TABLE locuri_de_veci (id INTEGER PRIMARY KEY AUTOINCREMENT, cod_loc TEXT UNIQUE, points TEXT, color TEXT, sector TEXT, parcela TEXT, rand TEXT, numar TEXT, capacitate TEXT, disponibilitate TEXT, tip TEXT, stare TEXT, categorie TEXT, suprafata REAL, nr_vechi TEXT, numar_cf TEXT, ocupat INTEGER DEFAULT 0, observatii TEXT);
CREATE TABLE concesionari (id INTEGER PRIMARY KEY AUTOINCREMENT, nume TEXT, prenume TEXT, cnp TEXT, bi_ci TEXT, adresa TEXT, telefon TEXT, email TEXT, observatii TEXT);
CREATE TABLE contracte (id INTEGER PRIMARY KEY AUTOINCREMENT, numar_contract TEXT, data_contract TEXT, data_inceput TEXT, data_sfarsit TEXT, concesionar_id INTEGER, id_loc INTEGER, observatii TEXT, FOREIGN KEY(concesionar_id) REFERENCES concesionari(id) ON DELETE SET NULL ON UPDATE CASCADE, FOREIGN KEY(id_loc) REFERENCES locuri_de_veci(id) ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE inhumati (id INTEGER PRIMARY KEY AUTOINCREMENT, nume TEXT, prenume TEXT, cnp TEXT, data_nasterii TEXT, data_deces TEXT, data_inhumare TEXT, data_deshumare TEXT, sex TEXT, cauza_deces TEXT, profesie TEXT, religie TEXT, ultima_adresa TEXT, observatii TEXT, id_loc INTEGER, FOREIGN KEY(id_loc) REFERENCES locuri_de_veci(id) ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE sectoare (id TEXT PRIMARY KEY, points TEXT, color TEXT);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE photos (id INTEGER PRIMARY KEY AUTOINCREMENT, cod_loc TEXT NOT NULL, file_path TEXT NOT NULL, caption TEXT, uploader TEXT, date_added TEXT, is_cover INTEGER DEFAULT 0, FOREIGN KEY(cod_loc) REFERENCES locuri_de_veci(cod_loc) ON DELETE CASCADE);
CREATE TABLE amenajari_avize (id INTEGER PRIMARY KEY AUTOINCREMENT, cod_loc TEXT NOT NULL, nr_aviz TEXT NOT NULL, data_aviz TEXT, created_at TEXT DEFAULT (datetime('now')), FOREIGN KEY(cod_loc) REFERENCES locuri_de_veci(cod_loc) ON DELETE CASCADE);
CREATE TABLE plati (id INTEGER PRIMARY KEY AUTOINCREMENT, cod_loc TEXT, suma REAL, data_plata TEXT, tip TEXT, chitanta_nr TEXT, observatii TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE documents (id INTEGER PRIMARY KEY AUTOINCREMENT, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, doc_type TEXT, file_path TEXT NOT NULL, caption TEXT, nr_evidenta TEXT, date_added TEXT);
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user', created_at TEXT NOT NULL, last_login TEXT);
